-- Walkthrough 009_seed_photo_fingerprints.sql
-- Paste the whole file into Supabase → SQL Editor → New query → Run. Safe to run again.
--
-- The six sample photos in public/seed/ were replaced with realistic ones, so their SHA-256 fingerprints changed.
-- This sets the new fingerprints on the sample rooms (rows whose photo path starts with /seed/). Without it, the
-- admin comparator shows "Mismatch" on sample photos that were fingerprinted before. Rooms with real uploads are
-- not touched. Generated by: node scripts/hash-seed.mjs (re-run that if you replace a photo again).

update inspection_items set before_sha256='06bf26148824dc04869532896c4355a02732bb47abd0aad660843f609c1c3e3e' where before_media_path='/seed/blinds-broken.jpg';
update inspection_items set after_sha256='06bf26148824dc04869532896c4355a02732bb47abd0aad660843f609c1c3e3e'  where after_media_path='/seed/blinds-broken.jpg';
update inspection_items set before_sha256='6780d9335a9bab427b81b0fad1235e5258ea3c169c2889520cb5535990c5dc9c' where before_media_path='/seed/blinds.jpg';
update inspection_items set after_sha256='6780d9335a9bab427b81b0fad1235e5258ea3c169c2889520cb5535990c5dc9c'  where after_media_path='/seed/blinds.jpg';
update inspection_items set before_sha256='4ee67eb0f70dce40a2c06e2996d12fc3710b21187eddf47afb46658e869ccbb7' where before_media_path='/seed/desk-water-ring.jpg';
update inspection_items set after_sha256='4ee67eb0f70dce40a2c06e2996d12fc3710b21187eddf47afb46658e869ccbb7'  where after_media_path='/seed/desk-water-ring.jpg';
update inspection_items set before_sha256='579885bad90240eff8aef07149b665b0a5757b74527e6aff858611861e9a9997' where before_media_path='/seed/desk.jpg';
update inspection_items set after_sha256='579885bad90240eff8aef07149b665b0a5757b74527e6aff858611861e9a9997'  where after_media_path='/seed/desk.jpg';
update inspection_items set before_sha256='319c1e5f9250a880e120210aca179d10b5635505bf296c55f1f433c44781f77f' where before_media_path='/seed/door.jpg';
update inspection_items set after_sha256='319c1e5f9250a880e120210aca179d10b5635505bf296c55f1f433c44781f77f'  where after_media_path='/seed/door.jpg';
update inspection_items set before_sha256='16174b3cdcae67f281f1413635281ee21014e839dc7d888a47afcdc1d280d242' where before_media_path='/seed/sink.jpg';
update inspection_items set after_sha256='16174b3cdcae67f281f1413635281ee21014e839dc7d888a47afcdc1d280d242'  where after_media_path='/seed/sink.jpg';

-- Should print one row: seed_photos_fingerprinted = true.
select not exists (select 1 from inspection_items where (before_media_path like '/seed/%' and before_sha256 is null)
                   or (after_media_path like '/seed/%' and after_sha256 is null)) as seed_photos_fingerprinted;
